// Prepared refinement for Vetalya Home (14:345). Not yet applied: Figma MCP Starter limit.
// Run as a Figma plugin main script with access to this file. All interface text stays editable.
async function refineVetalya() {
 const root=await figma.getNodeByIdAsync('14:345'); if(!root)throw new Error('Vetalya Home frame not found');
 let page=root;while(page.type!=='PAGE')page=page.parent;await figma.setCurrentPageAsync(page);
 const texts=root.findAllWithCriteria({types:['TEXT']});const fonts=new Map();
 for(const text of texts)for(const segment of text.getStyledTextSegments(['fontName']))fonts.set(JSON.stringify(segment.fontName),segment.fontName);
 await Promise.all([...fonts.values()].map(f=>figma.loadFontAsync(f)));
 await Promise.all(['Regular','Medium','SemiBold','Bold'].map(style=>figma.loadFontAsync({family:'Manrope',style})));
 const changed=[];
 for(const text of texts){const heading=text.fontSize>=16;const label=['Health','Meals','Activity','Weight','Book vet','Reminder','Records','Emergency'].includes(text.characters);text.fontName={family:'Manrope',style:heading?'Bold':label?'SemiBold':text.fontName.style==='Regular'?'Regular':'Medium'};text.lineHeight={unit:'PERCENT',value:130};changed.push(text.id);}
 const content=await figma.getNodeByIdAsync('14:355');content.y=48;content.resize(342,704);content.itemSpacing=12;changed.push(content.id);
 const row=await figma.getNodeByIdAsync('14:356');row.resize(342,92);changed.push(row.id);
 const greeting=await figma.getNodeByIdAsync('14:357');greeting.resize(278,92);greeting.itemSpacing=2;changed.push(greeting.id);
 for(const id of ['14:359','14:366']){const t=await figma.getNodeByIdAsync(id);t.fontSize=22;changed.push(id);}
 const old=await figma.getNodeByIdAsync('14:358');old.visible=false;changed.push(old.id);
 const created=[];let brand=greeting.children.find(n=>n.name==='Official Vetalya web brand');
 function decode64(value){const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';let buffer=0,bits=0;const bytes=[];for(const c of value){if(c==='=')break;const digit=alphabet.indexOf(c);if(digit<0)continue;buffer=(buffer<<6)|digit;bits+=6;if(bits>=8){bits-=8;bytes.push((buffer>>bits)&255);}}return new Uint8Array(bytes);}
 if(!brand){brand=figma.createFrame();brand.name='Official Vetalya web brand';brand.layoutMode='HORIZONTAL';brand.primaryAxisSizingMode='FIXED';brand.counterAxisSizingMode='FIXED';brand.itemSpacing=6;brand.counterAxisAlignItems='CENTER';brand.fills=[];greeting.insertChild(0,brand);brand.resize(118,32);created.push(brand.id);
  for(const [name,data,width] of [['Official emblem','',32],['Official wordmark','',80]]){const image=figma.createImage(decode64(data));const rect=figma.createRectangle();rect.name=name;brand.appendChild(rect);rect.resize(width,32);rect.fills=[{type:'IMAGE',imageHash:image.hash,scaleMode:'FIT'}];created.push(rect.id);}
 }
 root.name='11. Home — Vetalya · Bold aligned';changed.push(root.id);
 const bad=texts.filter(t=>t.fontName.family!=='Manrope');if(bad.length)throw new Error('Font mismatch');
 figma.viewport.scrollAndZoomIntoView([root]);return {mutatedNodeIds:changed,createdNodeIds:created,fontFamily:'Manrope',editableTextCount:texts.length};
}
refineVetalya().then(result=>console.log(result)).catch(error=>console.error(error));
